/**
 * ContextPackDto
 *
 * What a caller would otherwise discover by reading before it can act.
 *
 * It is the existing capability description, the existing compiled read
 * context and the existing preflight, composed for one named source and
 * focus. It proposes nothing: ``request`` is the template the capability
 * already reports, holding the values the record holds now.
 */
export type ContextPackDto = {
    /**
     * Contextpack
     */
    contextPack?: 'ContextPack@1';
    source: CapabilitySourceDto;
    /**
     * the focus element's numbers, as the catalog decided them; null when the capability reads no target for it
     */
    target?: CapabilityTargetDto | null;
    keep?: KeepScopeDto | null;
    /**
     * Request
     *
     * the capability's own next request with this project's base and the focus element's current values already in it; a template to edit, never an approved change. Null when the target has no number this capability can move, or when the preflight below already answers the request without one
     */
    request?: {
        [key: string]: unknown;
    } | null;
    /**
     * Contexttier
     *
     * which read context the existing compiler chose for these words: scalar, component or design
     */
    contextTier: string;
    /**
     * Escalation
     *
     * why the compiler widened the context, in its own reasons; empty when a narrow numeric reading was reached
     */
    escalation?: Array<string>;
    /**
     * Context
     *
     * the facts that reading makes available, as the existing model projection of it; it grants no edit and changes no reference
     */
    context: {
        [key: string]: unknown;
    };
    /**
     * Preflight
     *
     * the existing known obstacle to a numeric action — a lock, a derived value, a shared control, a top reference — as the record already answers it, needing no model call. Null when there is none and for the design tier, which this preflight does not judge
     */
    preflight?: {
        [key: string]: unknown;
    } | null;
    /**
     * Derived from verified committed design history, with differences from this exact source. Null when no committed Stage is bound; never inferred from an unaccepted candidate.
     */
    confirmedStage?: ConfirmedStageContextDto | null;
    /**
     * Scopeddecisions
     *
     * the decisions this project retains that still apply to this domain, Stage and focus, in the architect's own words with their exact provenance. Revoked, deferred, superseded and derived-stale ones are left out, and no transcript is carried; it authorizes nothing and changes no reference
     */
    scopedDecisions?: Array<DecisionDto>;
    /**
     * Studyevidence
     *
     * Read-only projections of explicitly selected Study revisions. Check each completeness and applicability result before using a prior; evidence never becomes a design decision or constraint.
     */
    studyEvidence?: Array<{
        [key: string]: unknown;
    }>;
    /**
     * Honesty
     */
    honesty?: Array<string>;
};

/**
 * ContextPackRequestDto
 *
 * One turn's words, plus the exact source and focus they were said about.
 *
 * An absent focus asks about the whole design. Named objects and sources are
 * checked exactly; no missing selection is replaced by a recent candidate.
 */
export type ContextPackRequestDto = {
    /**
     * Utterance
     *
     * the complete message the architect sent, unedited; it is read by the same context compiler an intent uses, so a request that names several objects keeps the wider context that reading needs
     */
    utterance: string;
    /**
     * Projectid
     *
     * the project the caller believes it is reading; a different one is refused as PROJECT_MISMATCH
     */
    projectId: string;
    /**
     * Sourcerunid
     *
     * the exact retained run; omit only for authored initial state or an explicit sourceStageRef
     */
    sourceRunId?: string | null;
    /**
     * Statedigest
     *
     * the stateDigest that run projects to; any other is refused as STALE_BASE
     */
    stateDigest: string;
    /**
     * Targetcomponentid
     *
     * optional exact Component@1 focus; when elements are named they must belong to it
     */
    targetComponentId?: string | null;
    /**
     * Elementid
     *
     * the Element@1 in focus; it must declare targetComponentId as its own component
     */
    elementId?: string | null;
    /**
     * Sourcestageref
     */
    sourceStageRef?: string | null;
    /**
     * Elementids
     */
    elementIds?: Array<string>;
    /**
     * Contextrefs
     */
    contextRefs?: Array<string>;
    /**
     * Contextoffset
     *
     * offset into the bounded reference index; it changes no focus or edit scope
     */
    contextOffset?: number;
    /**
     * Studyevidence
     *
     * Optional exact retained Study revisions to read as conditional precedent evidence. Each prior travels with its declared conditions and counterevidence; no latest revision is inferred.
     */
    studyEvidence?: Array<StudyRevisionRequestDto>;
    /**
     * what this turn is about for the scoped decisions it should be handed: the domain, and for a drawing or copy turn its own exact evidence. Absent, the design and drawing domains (the project recipe among the drawing decisions), this source's Stage and the focus already named above answer for it; naming a domain reads that domain alone
     */
    decisionContext?: DecisionContextDto | null;
};

